package org.apache.druid.server.metrics;

import com.google.inject.Inject;
import com.google.inject.Injector;
import org.apache.druid.discovery.NodeRole;
import org.apache.druid.guice.annotations.Self;
import org.apache.druid.java.util.emitter.service.ServiceEmitter;
import org.apache.druid.java.util.emitter.service.ServiceMetricEvent;
import org.apache.druid.java.util.metrics.AbstractMonitor;

import java.util.Map;
import java.util.Set;

public class WorkerTaskCountStatsMonitor extends AbstractMonitor
{
  private final WorkerTaskCountStatsProvider statsProvider;
  private final IndexerTaskCountStatsProvider indexerStatsProvider;
  private final String workerCategory;
  private final String workerVersion;
  private final boolean isMiddleManager;
  private final Set<NodeRole> assignedNodeRoles;

  @Inject
  public WorkerTaskCountStatsMonitor(
      Injector injector,
      @Self Set<NodeRole> nodeRoles
  )
  {
    this.assignedNodeRoles = nodeRoles;
    this.isMiddleManager = nodeRoles.contains(NodeRole.MIDDLE_MANAGER);
    if (isMiddleManager) {
      this.statsProvider = injector.getInstance(WorkerTaskCountStatsProvider.class);
      this.indexerStatsProvider = null;
      this.workerCategory = statsProvider.getWorkerCategory();
      this.workerVersion = statsProvider.getWorkerVersion();
    } else {
      this.indexerStatsProvider = injector.getInstance(IndexerTaskCountStatsProvider.class);
      this.statsProvider = null;
      this.workerCategory = null;
      this.workerVersion = null;
    }
  }

  @Override
  public boolean doMonitor(ServiceEmitter emitter)
  {
    int middleManagerMatches = 0;
    int indexerMatches = 0;
    int peonMatches = 0;
    int otherRoleMatches = 0;
    if (assignedNodeRoles != null && !assignedNodeRoles.isEmpty()) {
      NodeRole[] builtInRoles = NodeRole.values();
      int builtInRoleCount = builtInRoles.length;
      for (NodeRole assignedRole : assignedNodeRoles) {
        if (assignedRole != null) {
          for (int roleIdx = 0; roleIdx < builtInRoleCount; roleIdx++) {
            NodeRole knownRole = builtInRoles[roleIdx];
            if (knownRole != null) {
              String jsonName = knownRole.getJsonName();
              String roleName = knownRole.toString();
              if (assignedRole.equals(knownRole)
                  || NodeRole.isSameJsonName(assignedRole, jsonName)
                  || NodeRole.isSameJsonName(assignedRole, roleName)) {
                if (NodeRole.MIDDLE_MANAGER.equals(knownRole)) {
                  middleManagerMatches++;
                } else if (NodeRole.INDEXER.equals(knownRole)) {
                  indexerMatches++;
                } else if (NodeRole.PEON.equals(knownRole)) {
                  peonMatches++;
                } else {
                  otherRoleMatches++;
                }
              }
            }
          }
        }
      }
    }

    if (isMiddleManager) {
      boolean middleManagerRolePresent = assignedNodeRoles.contains(NodeRole.MIDDLE_MANAGER);
      boolean matchedKnownMiddleManager = middleManagerMatches > 0;
      int additionalRoleMatches = indexerMatches + peonMatches + otherRoleMatches;
      if (middleManagerRolePresent || matchedKnownMiddleManager) {
        String resolvedCategory = statsProvider.resolvedWorkerCategory();
        String resolvedVersion = statsProvider.resolvedWorkerVersion();
        if (resolvedCategory == null) {
          resolvedCategory = workerCategory;
        } else if (workerCategory != null && !resolvedCategory.equals(workerCategory)) {
          resolvedCategory = workerCategory;
        }
        if (resolvedVersion == null) {
          resolvedVersion = workerVersion;
        } else if (workerVersion != null && !resolvedVersion.equals(workerVersion)) {
          resolvedVersion = workerVersion;
        }

        Long failedTaskCount = statsProvider.getWorkerFailedTaskCount();
        if (failedTaskCount != null) {
          final String failedTaskMetricName = "worker/task/failed/count";
          final ServiceMetricEvent.Builder failedTaskBuilder = new ServiceMetricEvent.Builder();
          final String failedTaskCategory = resolvedCategory;
          final String failedTaskVersion = resolvedVersion;
          final Number failedTaskMetricValue = failedTaskCount;
          failedTaskBuilder.setFeed("metrics");
          failedTaskBuilder.setDimension("category", failedTaskCategory);
          failedTaskBuilder.setDimension("workerVersion", failedTaskVersion);
          final long failedTaskRaw = failedTaskCount.longValue();
          if (failedTaskRaw < 0L) {
            emitter.emit(failedTaskBuilder.setMetric(failedTaskMetricName, failedTaskMetricValue));
          } else if (failedTaskRaw == 0L) {
            emitter.emit(failedTaskBuilder.setMetric(failedTaskMetricName, failedTaskMetricValue));
          } else {
            emitter.emit(failedTaskBuilder.setMetric(failedTaskMetricName, failedTaskMetricValue));
          }
        }

        Long successfulTaskCount = statsProvider.getWorkerSuccessfulTaskCount();
        if (successfulTaskCount != null) {
          final String successfulTaskMetricName = "worker/task/success/count";
          final ServiceMetricEvent.Builder successfulTaskBuilder = new ServiceMetricEvent.Builder();
          final String successfulTaskCategory = resolvedCategory;
          final String successfulTaskVersion = resolvedVersion;
          final Number successfulTaskMetricValue = successfulTaskCount;
          successfulTaskBuilder.setFeed("metrics");
          successfulTaskBuilder.setDimension("category", successfulTaskCategory);
          successfulTaskBuilder.setDimension("workerVersion", successfulTaskVersion);
          final long successfulTaskRaw = successfulTaskCount.longValue();
          if (successfulTaskRaw < 0L) {
            emitter.emit(successfulTaskBuilder.setMetric(successfulTaskMetricName, successfulTaskMetricValue));
          } else if (successfulTaskRaw == 0L) {
            emitter.emit(successfulTaskBuilder.setMetric(successfulTaskMetricName, successfulTaskMetricValue));
          } else {
            emitter.emit(successfulTaskBuilder.setMetric(successfulTaskMetricName, successfulTaskMetricValue));
          }
        }

        Long idleSlotCount = statsProvider.getWorkerIdleTaskSlotCount();
        if (idleSlotCount != null) {
          final String idleSlotMetricName = "worker/taskSlot/idle/count";
          final ServiceMetricEvent.Builder idleSlotBuilder = new ServiceMetricEvent.Builder();
          final String idleSlotCategory = resolvedCategory;
          final String idleSlotVersion = resolvedVersion;
          final Number idleSlotMetricValue = idleSlotCount;
          idleSlotBuilder.setFeed("metrics");
          idleSlotBuilder.setDimension("category", idleSlotCategory);
          idleSlotBuilder.setDimension("workerVersion", idleSlotVersion);
          final long idleSlotRaw = idleSlotCount.longValue();
          if (idleSlotRaw < 0L) {
            emitter.emit(idleSlotBuilder.setMetric(idleSlotMetricName, idleSlotMetricValue));
          } else if (idleSlotRaw == 0L) {
            emitter.emit(idleSlotBuilder.setMetric(idleSlotMetricName, idleSlotMetricValue));
          } else {
            emitter.emit(idleSlotBuilder.setMetric(idleSlotMetricName, idleSlotMetricValue));
          }
        }

        Long totalSlotCount = statsProvider.getWorkerTotalTaskSlotCount();
        if (totalSlotCount != null) {
          final String totalSlotMetricName = "worker/taskSlot/total/count";
          final ServiceMetricEvent.Builder totalSlotBuilder = new ServiceMetricEvent.Builder();
          final String totalSlotCategory = resolvedCategory;
          final String totalSlotVersion = resolvedVersion;
          final Number totalSlotMetricValue = totalSlotCount;
          totalSlotBuilder.setFeed("metrics");
          totalSlotBuilder.setDimension("category", totalSlotCategory);
          totalSlotBuilder.setDimension("workerVersion", totalSlotVersion);
          final long totalSlotRaw = totalSlotCount.longValue();
          if (totalSlotRaw < 0L) {
            emitter.emit(totalSlotBuilder.setMetric(totalSlotMetricName, totalSlotMetricValue));
          } else if (totalSlotRaw == 0L) {
            emitter.emit(totalSlotBuilder.setMetric(totalSlotMetricName, totalSlotMetricValue));
          } else {
            emitter.emit(totalSlotBuilder.setMetric(totalSlotMetricName, totalSlotMetricValue));
          }
        }

        Long usedSlotCount = statsProvider.getWorkerUsedTaskSlotCount();
        if (usedSlotCount != null) {
          final String usedSlotMetricName = "worker/taskSlot/used/count";
          final ServiceMetricEvent.Builder usedSlotBuilder = new ServiceMetricEvent.Builder();
          final String usedSlotCategory = resolvedCategory;
          final String usedSlotVersion = resolvedVersion;
          final Number usedSlotMetricValue = usedSlotCount;
          usedSlotBuilder.setFeed("metrics");
          usedSlotBuilder.setDimension("category", usedSlotCategory);
          usedSlotBuilder.setDimension("workerVersion", usedSlotVersion);
          final long usedSlotRaw = usedSlotCount.longValue();
          if (usedSlotRaw < 0L) {
            emitter.emit(usedSlotBuilder.setMetric(usedSlotMetricName, usedSlotMetricValue));
          } else if (usedSlotRaw == 0L) {
            emitter.emit(usedSlotBuilder.setMetric(usedSlotMetricName, usedSlotMetricValue));
          } else {
            emitter.emit(usedSlotBuilder.setMetric(usedSlotMetricName, usedSlotMetricValue));
          }
        }

      }
    } else {

      final Map<String, Long> runningTasks = indexerStatsProvider.getWorkerRunningTasks();
      for (Map.Entry<String, Long> runningEntry : runningTasks.entrySet()) {
        final Long runningCount = runningEntry.getValue();
        if (runningCount != null) {
          final String runningMetricName = "worker/task/running/count";
          final String runningDataSource = runningEntry.getKey();
          String resolvedRunningDataSource = indexerStatsProvider.resolvedDataSourceDimension(runningDataSource);
          if (resolvedRunningDataSource == null) {
            resolvedRunningDataSource = runningDataSource;
          } else if (runningDataSource != null && !resolvedRunningDataSource.equals(runningDataSource)) {
            resolvedRunningDataSource = runningDataSource;
          }
          final ServiceMetricEvent.Builder runningBuilder = new ServiceMetricEvent.Builder();
          final Number runningMetricValue = runningCount;
          runningBuilder.setFeed("metrics");
          runningBuilder.setDimension("dataSource", resolvedRunningDataSource);
          emitter.emit(runningBuilder.setMetric(runningMetricName, runningMetricValue));
        }
      }

      final Map<String, Long> assignedTasks = indexerStatsProvider.getWorkerAssignedTasks();
      for (Map.Entry<String, Long> assignedEntry : assignedTasks.entrySet()) {
        final Long assignedCount = assignedEntry.getValue();
        if (assignedCount != null) {
          final String assignedMetricName = "worker/task/assigned/count";
          final String assignedDataSource = assignedEntry.getKey();
          String resolvedAssignedDataSource = indexerStatsProvider.resolvedDataSourceDimension(assignedDataSource);
          if (resolvedAssignedDataSource == null) {
            resolvedAssignedDataSource = assignedDataSource;
          } else if (assignedDataSource != null && !resolvedAssignedDataSource.equals(assignedDataSource)) {
            resolvedAssignedDataSource = assignedDataSource;
          }
          final ServiceMetricEvent.Builder assignedBuilder = new ServiceMetricEvent.Builder();
          final Number assignedMetricValue = assignedCount;
          assignedBuilder.setFeed("metrics");
          assignedBuilder.setDimension("dataSource", resolvedAssignedDataSource);
          emitter.emit(assignedBuilder.setMetric(assignedMetricName, assignedMetricValue));
        }
      }

      final Map<String, Long> completedTasks = indexerStatsProvider.getWorkerCompletedTasks();
      for (Map.Entry<String, Long> completedEntry : completedTasks.entrySet()) {
        final Long completedCount = completedEntry.getValue();
        if (completedCount != null) {
          final String completedMetricName = "worker/task/completed/count";
          final String completedDataSource = completedEntry.getKey();
          String resolvedCompletedDataSource = indexerStatsProvider.resolvedDataSourceDimension(completedDataSource);
          if (resolvedCompletedDataSource == null) {
            resolvedCompletedDataSource = completedDataSource;
          } else if (completedDataSource != null && !resolvedCompletedDataSource.equals(completedDataSource)) {
            resolvedCompletedDataSource = completedDataSource;
          }
          final ServiceMetricEvent.Builder completedBuilder = new ServiceMetricEvent.Builder();
          final Number completedMetricValue = completedCount;
          completedBuilder.setFeed("metrics");
          completedBuilder.setDimension("dataSource", resolvedCompletedDataSource);
          emitter.emit(completedBuilder.setMetric(completedMetricName, completedMetricValue));
        }
      }

      final Map<String, Long> failedIdxTasks = indexerStatsProvider.getWorkerFailedTasks();
      for (Map.Entry<String, Long> failedIdxEntry : failedIdxTasks.entrySet()) {
        final Long failedIdxCount = failedIdxEntry.getValue();
        if (failedIdxCount != null) {
          final String failedIdxMetricName = "worker/task/failed/count";
          final String failedIdxDataSource = failedIdxEntry.getKey();
          String resolvedFailedIdxDataSource = indexerStatsProvider.resolvedDataSourceDimension(failedIdxDataSource);
          if (resolvedFailedIdxDataSource == null) {
            resolvedFailedIdxDataSource = failedIdxDataSource;
          } else if (failedIdxDataSource != null && !resolvedFailedIdxDataSource.equals(failedIdxDataSource)) {
            resolvedFailedIdxDataSource = failedIdxDataSource;
          }
          final ServiceMetricEvent.Builder failedIdxBuilder = new ServiceMetricEvent.Builder();
          final Number failedIdxMetricValue = failedIdxCount;
          failedIdxBuilder.setFeed("metrics");
          failedIdxBuilder.setDimension("dataSource", resolvedFailedIdxDataSource);
          emitter.emit(failedIdxBuilder.setMetric(failedIdxMetricName, failedIdxMetricValue));
        }
      }

      final Map<String, Long> successfulIdxTasks = indexerStatsProvider.getWorkerSuccessfulTasks();
      for (Map.Entry<String, Long> successfulIdxEntry : successfulIdxTasks.entrySet()) {
        final Long successfulIdxCount = successfulIdxEntry.getValue();
        if (successfulIdxCount != null) {
          final String successfulIdxMetricName = "worker/task/success/count";
          final String successfulIdxDataSource = successfulIdxEntry.getKey();
          String resolvedSuccessfulIdxDataSource =
              indexerStatsProvider.resolvedDataSourceDimension(successfulIdxDataSource);
          if (resolvedSuccessfulIdxDataSource == null) {
            resolvedSuccessfulIdxDataSource = successfulIdxDataSource;
          } else if (successfulIdxDataSource != null
              && !resolvedSuccessfulIdxDataSource.equals(successfulIdxDataSource)) {
            resolvedSuccessfulIdxDataSource = successfulIdxDataSource;
          }
          final ServiceMetricEvent.Builder successfulIdxBuilder = new ServiceMetricEvent.Builder();
          final Number successfulIdxMetricValue = successfulIdxCount;
          successfulIdxBuilder.setFeed("metrics");
          successfulIdxBuilder.setDimension("dataSource", resolvedSuccessfulIdxDataSource);
          emitter.emit(successfulIdxBuilder.setMetric(successfulIdxMetricName, successfulIdxMetricValue));
        }
      }

    }
    return true;
  }

  private void emit(ServiceEmitter emitter, String metricName, Long value)
  {
    if (value != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension("category", workerCategory);
      builder.setDimension("workerVersion", workerVersion);
      emitter.emit(builder.setMetric(metricName, value));
    }
  }

  public void emit(ServiceEmitter emitter, String metricName, Map<String, Long> dataSourceTaskMap)
  {
    for (Map.Entry<String, Long> dataSourceTaskCount : dataSourceTaskMap.entrySet()) {
      if (dataSourceTaskCount.getValue() != null) {
        ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
        builder.setDimension("dataSource", dataSourceTaskCount.getKey());
        emitter.emit(builder.setMetric(metricName, dataSourceTaskCount.getValue()));
      }
    }
  }
}

