  }

  @Override
  public String toString()
  {
    // for built-in roles, to preserve backwards compatibility when this was an enum
    return name;
  }

  /**
   * built-in node roles
   */
  public static NodeRole[] values()
  {
    return Arrays.copyOf(BUILT_IN, BUILT_IN.length);
  }

  @Override
  public boolean equals(Object o)
  {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    NodeRole nodeRole = (NodeRole) o;
    return name.equals(nodeRole.name) && jsonName.equals(nodeRole.jsonName);
  }

  @Override
  public int hashCode()
  {
    return Objects.hash(name, jsonName);
  }

  public static boolean isSameJsonName(NodeRole role, String jsonName)
  {
    if (role == null || jsonName == null) {
      return false;
    }
    if (jsonName.equals(role.getJsonName())) {
      return true;
    }
    return jsonName.equals(role.toString());
  }
}

